"""Reading structure for individually reviewed weeks with five extension tasks."""
from connected_level_authoring import LevelAuthor,g
class ExtendedAuthor(LevelAuthor):
 def records(self,case,check,tasks,lab,extension,extras=None):
  D=self.design;w=self.w;extras=extras or {}
  assert len(w['workbook']) in (26,31)
  shift=len(w['workbook'])-26
  D('sections',5,'Reference · Words for the main lesson and extension','Use each word with a concrete record or calculation.',[g('Core words',[7]),g('Main explanation terms',[9])]+([g('Extension terms',[11])] if len(w['sections'][4]['blocks'])>11 else []),True)
  D('sections',10,'Extra challenge · Choose a stronger explanation','Choose the next useful challenge rather than repeating the ladder.',[g('Thinking ladder',list(range(4,11)),'prompts')],True)
  D('sections',12,'Reference · Check your explanation','Use after practice; '+case+' is the selected independent task.',[g('Evidence and limits',[5,6,7,8,9,10],'prompts'),g('Self-check',[11])],True)
  D('sections',13,'Extra practice · The earlier complete case','Try the question before opening the worked explanation.',[g('Question and given facts',[3,5]),g('Your explanation',[9,10],'prompts'),g('Check after trying',[7]+[i for i,b in enumerate(w['sections'][12]['blocks']) if b['type']=='table'],'example',True)],True)
  D('sections',15,'Reference · Earlier checklist','Use when it helps inspect the evidence.',[g('Checklist and first prediction',[1,2,3])],True)
  for role,n in [('sections',17),('workbook',25+shift)]:
   bs=w[role][n-1]['blocks'];tail=[i for i in range(19,len(bs)) if bs[i]['type']!='subheading']
   D(role,n,'Extra practice · Pictures, feedback and repair','Try before opening feedback; keep the selected independent task separate.',[g('First supported question',list(range(1,10)),'prompts'),g('Check after trying',[10],'example',True),g('Changed-case question',list(range(11,18)),'prompts'),g('Check changed case',[18],'example',True),g('Repair and keep evidence',tail)],True)
  D('sections',18,'Reference · The six-picture journey','Revisit the picture that serves the current question.',[g(w['sections'][17]['blocks'][4*i]['text'],list(range(4*i+1,4*i+4))) for i in range(6)],True)
  bs=w['teacher'][0]['blocks'];pre=self.find('teacher',1,'Preparation for the connected explanation');ready=self.find('teacher',1,'Readiness answer');prep=self.find('teacher',1,'Prepare the class');end=self.find('teacher',1,'End goal for the pictorial case')
  recall=[i for i in range(5,prep) if bs[i]['type']=='paragraph' and bs[i]['text'].startswith(('Without opening','Look for:','Reference example'))]
  D('teacher',1,'Prepare the main lesson and its retained extension','Use fictional records and schedule separate extension time.',[g('Goal and preparation',[1,pre+1,end+1,prep+1]),g('Main plan',[2,3]),g('Retrieval and readiness',recall+[ready+1]),g('Materials and extension planning',list(range(ready+2,end)),'reference',True)])
  c=self.find('teacher',3,'Completion task:');q=self.find('teacher',3,'Use the worked case for');pq=self.find('teacher',3,'Pictorial practice question');pk=self.find('teacher',3,'Reasoned teacher answer');ext=self.find('teacher',3,'Connected teaching cycle:')
  D('teacher',3,'Guide the main explanation, then fade support','Collect each learner’s reasoning before revealing a key.',[g('Main completion question and key',[c,c+1,c+2]),g('Main individual check',[q,q+1,q+2]),g('Pictorial question and changed case',[pq+1,pk+1,pk+2,pk+3]),g('Keep learners explaining',[self.find('teacher',3,'Classroom dialogue')+i for i in [1,2,4]]),g('Extension teaching cycle',list(range(ext+1,pq)),'reference',True)])
  key=self.add('teacher',4,lab);support=self.find('teacher',4,'Match the support to the first error');mis=self.find('teacher',4,'Address these additional misconceptions');exmis=self.find('teacher',4,'Check these misconceptions')
  D('teacher',4,'Run the supplied main investigation','Keep the selected independent task out of shared practice.',[g('Supplied records and answer guidance',[key]),g('Predict, investigate and record',[3,4,5,6],'steps'),g('Keep the evidence',[9]),g('Main misconceptions',list(range(mis+1,exmis)),'cards'),g('Choose support',list(range(support+1,key))),g('Extension misconceptions',list(range(exmis+1,support)),'reference',True)])
  selected=self.find('teacher',5,'Selected case:');bs=w['teacher'][4]['blocks'];groups=[g('Selected independent question and key',[selected,selected+2],'example'),g('Judge reasoning and limits',[selected+3,selected+4]),g('Give one repair action',[selected+6])]
  for number in [1,2,3,5]:
   h=next(i for i,b in enumerate(bs) if b['type']=='subheading' and b.get('text','').startswith('W'+str(number)+' '));stop=next(i for i in range(h+1,len(bs)) if bs[i]['type']=='subheading');groups.append(g(bs[h]['text'],list(range(h+1,stop))))
  extension_start=next(i for i,b in enumerate(bs) if b['type']=='subheading' and b.get('text','').startswith(extension+' —'))
  groups.append(g('Extension questions and keys',list(range(extension_start,selected-1)),'reference',True));D('teacher',5,'Assess the selected main independent task','Reveal its key after the first attempt; extension tasks have their own keys.',groups)
  delay=self.find('teacher',6,'Plan the delayed return');project=self.find('teacher',6,'Project evidence from this case');ex=self.find('teacher',6,'Readiness and reassessment for')
  D('teacher',6,'Connect, support and return','Keep main and extension assessment evidence distinguishable.',[g('Project record',[3,project+1]),g('Main support and fresh assessment',[11,12]),g('Delayed return',list(range(delay+1,project))),g('Bridge to next week',[7,9,13]),g('Extension support and reassessment',list(range(ex+1,delay)),'reference',True)])
  D('teacher',7,'Reference · Alternative teaching checklist','Use as a reminder alongside the main route.',[g('Planning reference',list(range(13)))],True)
  D('teacher',8,'Reference · Feedback and retained evidence','Keep supported practice separate from independent evidence.',[g('Record and repair',[0,1,3,4])],True)
  D('teacher',9,'Reference · Teach with the six pictures','Choose a picture for a specific explanation.',[g(w['teacher'][8]['blocks'][1+5*i]['text'],list(range(2+5*i,6+5*i))) for i in range(6)],True)
  for n,title,purpose in [(1,'Recall · Retrieve earlier ideas','Try before opening notes.'),*tasks,(4,'W4 · '+case,'Keep the first attempt before hints.'),(9,'Project · Keep the decision and evidence','Extend the existing project record.'),(10,'Finish · Judge your evidence','Point to work that supports your judgement.'),(22+shift,'Feedback · Repair and return','Keep first attempt, repair and a changed-case check.')]:
   indices=extras.get(n,[])+[i for i,b in enumerate(self.original['workbook'][n-1]['blocks']) if b['type']!='subheading'];D('workbook',n,title,purpose,[g('Your evidence record',indices,'prompts')])
  refs={2:'Reference · Supported W2 record',3:'Extra practice · Repair a claim',5:'Reference · Earlier target',6:'Extra practice · Earlier worked case',7:'Extra practice · Changed case',8:'Extra practice · A revealing test',11:'Extra practice · Earlier transfer',15:'Reference · Selected W4 response copy',23+shift:'Extra practice · Pictured case',24+shift:'Reference · Project milestone'}
  for n,title in refs.items():D('workbook',n,title,'Use when helpful; keep this practice separate from the selected first attempt.',[g('Additional evidence',list(range(len(w['workbook'][n-1]['blocks']))))],True)
  for n in range(17,22+shift):D('workbook',n,'Extension · '+w['workbook'][n-1]['title'],'Retained extension task with its own teacher key and response.',[g('Extension question and record',list(range(len(w['workbook'][n-1]['blocks']))),'prompts')],True)
  D('workbook',26+shift,'Reference · Six-picture response sheets','Choose the relevant picture rather than repeating every task.',[g(w['workbook'][25+shift]['blocks'][5*i]['text'],list(range(5*i+1,5*i+5))) for i in range(6)],True)
  self.fix('teacher',3,self.find('teacher',3,'Keep for an independent attempt:'),'Use the earlier transfer question as optional practice. Reserve '+case+' for the first independent attempt before hints or feedback.')
  self.fix('teacher',4,8,'Use the supplied main investigation for shared practice. Reserve '+case+' for the individual first attempt. The named extension has separate tasks and feedback.')
  self.fix('teacher',5,3,'Additional transfer practice');self.fix('teacher',5,5,'Reasoned practice answer');self.fix('workbook',7,1,'My practice reasoning');self.fix('workbook',11,1,'My explanation after practice')
  self.fix('sections',12,1,'Checklist for this week’s explanation');self.fix('sections',12,2,'Use after practice. '+case+' is the selected independent task.');self.fix('sections',12,4,check)
